import json
import sys

def pathfind():
    global input_data
    if 'input_data' not in globals():
        try:
            input_data = json.loads(sys.argv[1]) if len(sys.argv) > 1 else {}
        except Exception:
            input_data = {}

    start_x = int(input_data.get('start_x', -1))
    start_y = int(input_data.get('start_y', -1))
    target_x = int(input_data.get('target_x', -1))
    target_y = int(input_data.get('target_y', -1))
    map_id = input_data.get('map_id', '')

    blocked = set()
    width, height = 100, 100

    # Outer boundaries for B2F
    if map_id == '0_200': # B2F
        width, height = 29, 26
        for x in range(width):
            blocked.add((x, 0))
            blocked.add((x, height - 1))
        for y in range(height):
            blocked.add((0, y))
            blocked.add((width - 1, y))

    # Load specific floor colliders
    if map_id == '0_199': # B1F
        for y in range(35):
            blocked.add((8, y))
        for x in range(9, 24):
            blocked.add((x, 16))
        blocked.add((28, 16))
        blocked.add((24, 16))
        blocked.add((25, 16))

    elif map_id == '0_200': # B2F
        b2f_blocked_list = [
            *[(x, 16) for x in range(18, 28)],
            *[(18, y) for y in range(6, 10)],
            *[(17, y) for y in [8, 9, 12]],
            *[(24, y) for y in range(8, 14)],
            *[(23, y) for y in range(6, 14)],
            (6, 7),
            *[(x, 8) for x in [2, 3, 4, 6, 8, 10]],
            *[(x, 10) for x in [1, 2, 5, 6, 7, 8, 9, 11]],
            (2, 11), (11, 11),
            *[(x, 12) for x in [2, 4, 5, 7, 9, 11]],
            *[(x, 13) for x in [5, 6, 7, 9]],
            (2, 14), (3, 14),
            (12, 14), (13, 14), (14, 14), (15, 14),
            (12, 15), (13, 15), (15, 12), (16, 12), (17, 12), (15, 13),
            *[(17, y) for y in range(14, 17)],
            (15, 15),
            (14, 19), (15, 19), (15, 20), (15, 21), (15, 22),
            (11, 21), (12, 21), (13, 21),
            *[(x, 24) for x in range(11, 16)],
            *[(15, y) for y in range(19, 23)],
            *[(x, 21) for x in range(11, 14)],
            *[(x, 17) for x in range(17, 19)],
            *[(17, y) for y in range(18, 20)],
            *[(18, y) for y in range(14, 17)],
            *[(18, y) for y in range(18, 21)],
            (18, 22)
        ]
        for b in b2f_blocked_list:
            blocked.add(b)

    elif map_id == '0_201': # B3F
        for y in range(35):
            for x in range(9):
                blocked.add((x, y))
            for x in range(29, 100):
                blocked.add((x, y))
        for y in range(8, 17):
            blocked.add((21, y))
        for y in range(17, 27):
            blocked.add((23, y))
        for x in range(9, 24):
            blocked.add((x, 16))
        for y in range(22, 26):
            blocked.add((9, y))
        for x in [12, 13]:
            for y in range(22, 24):
                blocked.add((x, y))
        for x in range(12, 18):
            for y in range(18, 22):
                blocked.add((x, y))
        for y in range(19, 24):
            blocked.add((22, y))
        for x in range(8, 19):
            blocked.add((x, 8))
        for x in range(22, 26):
            blocked.add((x, 9))
        for x in range(9, 13):
            blocked.add((x, 10))
        for x in range(15, 20):
            blocked.add((x, 10))
        for x in range(24, 29):
            blocked.add((x, 13))
        for x in range(22, 29):
            blocked.add((x, 19))
        for x in range(22, 29):
            blocked.add((x, 20))
        blocked.add((19, 17))

    elif map_id == '0_202': # B4F
        for y in range(35):
            for x in range(9):
                blocked.add((x, y))
            for x in range(29, 100):
                blocked.add((x, y))
        for x in range(10, 14):
            blocked.add((x, 4))
        for x in range(18, 29):
            blocked.add((x, 4))
        for x in range(9, 16):
            blocked.add((x, 7))
        for x in range(22, 26):
            blocked.add((x, 9))
        for y in range(5, 13):
            blocked.add((16, y))
        for y in range(11, 14):
            blocked.add((10, y))
            blocked.add((11, y))
        blocked.add((14, 12))
        blocked.add((15, 12))
        for x in range(24, 29):
            blocked.add((x, 13))
        blocked.add((20, 13))
        blocked.add((21, 13))
        for y in range(4, 14):
            blocked.add((21, y))
        for y in range(13, 17):
            blocked.add((19, y))
        for x in range(10, 20):
            blocked.add((x, 16))
        for x in range(10, 18):
            blocked.add((x, 17))

    spinners = {}
    stop_tiles = set()

    if map_id == '0_200': # B2F Spinners & Stop Tiles
        spinners = {
            (4, 9): 'Left', (4, 11): 'Right', (4, 15): 'Right', (5, 14): 'Right',
            (8, 9): 'Left', (8, 12): 'Up', (8, 15): 'Up', (9, 14): 'Down',
            (10, 9): 'Left', (10, 10): 'Up', (10, 15): 'Up', (11, 14): 'Down',
            (12, 9): 'Left', (13, 10): 'Down', (17, 10): 'Left', (12, 11): 'Up',
            (17, 11): 'Left', (13, 12): 'Right', (8, 12): 'Up', (12, 13): 'Up',
            (5, 14): 'Right', (11, 14): 'Down', (16, 14): 'Up', (4, 15): 'Right',
            (8, 15): 'Up', (10, 15): 'Up', (4, 16): 'Up', (11, 16): 'Right',
            (13, 16): 'Right', (15, 16): 'Down', (16, 16): 'Up', (12, 17): 'Right',
            (14, 17): 'Up', (11, 18): 'Down', (13, 18): 'Left', (16, 18): 'Up',
            (13, 19): 'Left', (10, 25): 'Right', (13, 22): 'Left', (9, 22): 'Down'
        }
        stop_tiles = {
            (2, 9), (8, 11), (14, 15), (9, 16),
            (15, 18), (11, 20), (9, 24), (14, 25),
            (16, 13), (14, 12)
        }

    dirs = {
        'Up': (0, -1),
        'Down': (0, 1),
        'Left': (-1, 0),
        'Right': (1, 0)
    }

    def simulate_step(x, y, d):
        dx, dy = dirs[d]
        nx, ny = x + dx, y + dy
        if (nx, ny) in blocked or nx < 0 or nx >= width or ny < 0 or ny >= height:
            return None

        curr_x, curr_y = nx, ny
        while True:
            if (curr_x, curr_y) in stop_tiles:
                return (curr_x, curr_y)
            if (curr_x, curr_y) in spinners:
                spin_d = spinners[(curr_x, curr_y)]
                sdx, sdy = dirs[spin_d]
                nnx, nny = curr_x + sdx, curr_y + sdy
                if (nnx, nny) in blocked or nnx < 0 or nnx >= width or nny < 0 or nny >= height:
                    return (curr_x, curr_y)
                curr_x, curr_y = nnx, nny
                continue
            return (curr_x, curr_y)

    if start_x < 0 or start_y < 0 or target_x < 0 or target_y < 0:
        print("[]")
        return

    if (start_x, start_y) == (target_x, target_y):
        print("[]")
        return

    from collections import deque
    queue = deque([(start_x, start_y, [])])
    visited = {(start_x, start_y)}

    path_found = False
    buttons = []

    while queue:
        cx, cy, path = queue.popleft()
        if (cx, cy) == (target_x, target_y):
            path_found = True
            buttons = path
            break

        for d in ['Up', 'Down', 'Left', 'Right']:
            res = simulate_step(cx, cy, d)
            if res is not None:
                rx, ry = res
                if (rx, ry) not in visited:
                    visited.add((rx, ry))
                    queue.append((rx, ry, path + [d]))

    if path_found:
        print(json.dumps(buttons))
    else:
        print("[]")

if __name__ == '__main__':
    pathfind()
